ruleSearch.bookList:
@js:
(function(){
  try{
    var s = String(result || '');
    var out = [];
    var re = /<li>([\s\S]*?)<\/li>/g;
    var m = null;
    while((m = re.exec(s)) !== null){
      var b = m[1];
      var hm = b.match(/href="(\/album\/[0-9]+-[0-9]+\.html)"/);
      if(!hm) continue;
      var im = b.match(/<img[^>]+src="([^"]+)"/);
      var tm = b.match(/class="s-tit"[\s\S]*?<a[^>]*>([^<]*)/);
      var dm = b.match(/class="s-des">([\s\S]*?)<\/span>/);
      var t = tm ? String(tm[1]).replace(/<[^>]+>/g,'') : '';
      t = t.replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').trim();
      if(!t) continue;
      var ds = dm ? String(dm[1]).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ') : '';
      out.push({name:t, author:'', cover: im ? String(im[1]) : '',
                url:'https://www.shuyinfm.com' + hm[1], intro:ds});
    }
    if(out.length === 0){
      out.push({name:'[诊断]未解析到书目', author:'HTML长度=' + s.length,
                cover:'', url:'https://www.shuyinfm.com/',
                intro:'前300字符: ' + String(s).substring(0,300)});
    }
    return out;
  }catch(e){
    return [{name:'[异常]' + String(e.message), author:'', cover:'',
             url:'https://www.shuyinfm.com/', intro:'HTML长度=' + String(result||'').length}];
  }
})()

